    "crops": ["soybean", "corn", "wheat"],
    "livestock": ["dairy_cow", "chicken"],
    "seasons": ["autumn_winter", "spring_summer"]
  },
  "resources": {
    "land_available": "$$100$$",
    "capital_available": "$$15000$$"
  },
  "seasonal_data": {
    "labor_available": {
      "autumn_winter": "$$3500$$",
      "spring_summer": "$$4000$$"
    },
    "external_wage": {
      "autumn_winter": "$$1.8$$",
      "spring_summer": "$$2.1$$"
    }
  },
  "crop_data": {
    "seasonal_labor_per_land": {
      "autumn_winter": ["$$20$$", "$$35$$", "$$10$$"],
      "spring_summer": ["$$50$$", "$$75$$", "$$40$$"]
    },
    "annual_net_income_per_land": ["$$175$$", "$$300$$", "$$120$$"]
  },
  "livestock_data": {
    "investment_per_head": ["$$400$$", "$$3$$"],
    "land_per_head": ["$$1.5$$", "$$0$$"],
    "seasonal_labor_per_head": {
